    outputSchema: z.object({ total: z.number(), status: z.string() }),
  },
  async ({ orderId }) => ({
    content: [{ type: "text", text: `Order ${orderId}: ...` }],
    structuredContent: { total: 129, status: "shipped" },
  })
);
