function validateArgs(schema, args) {
  const problems = [];
  for (const [k, rule] of Object.entries(schema)) {
    const v = args[k];
    if (v === undefined) { if (rule.required) problems.push('missing:' + k); continue; }
    if (rule.pattern && !new RegExp(rule.pattern).test(v)) problems.push('bad-format:' + k);
    if (rule.max && v.length > rule.max) problems.push('too-long:' + k);
  }
  return problems.length ? { ok: false, isError: true, problems } : { ok: true };
}
const orderSchema = { orderId: { required: true, pattern: '^ORD-[0-9]+$' } };
console.log(JSON.stringify(validateArgs(orderSchema, { orderId: 'ORD-4821' })));
console.log(JSON.stringify(validateArgs(orderSchema, { orderId: 'ten' })));
console.log(JSON.stringify(validateArgs(orderSchema, {})));

